# Idea 1: Reflect one side to become symmetric with itself
# If we want perfect symmetry (mirrored), the output might be:
def create_symmetric(grid):
    rows, cols = len(grid), len(grid[0])
    center = cols // 2
    result = [[0]*cols for _ in range(rows)]

    # Copy left side, fill center with 5, copy right side mirrored
    for r in range(rows):
        for c in range(center + 1):
            if c == center:
                result[r][c] = 5
            elif c < center:
                # Mirror from left to right
                mirror_c = 2*center - c
                result[r][mirror_c] = grid[r][c]

    return result

print("Perfectly symmetric version:")
sym = create_symmetric(grid)
for row in sym:
    print(row)

# Idea 2: The 5 is removed, and both sides are merged
def merge_sides(grid):
    rows, cols = len(grid), len(grid[0])
    center = cols // 2
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if c == center:
                continue  # Skip the 5
            val = grid[r][c]
            if val != 0:
                result[r][c] = val

    return result

print("\nMerged (no 5):")
merged = merge_sides(grid)
for row in merged:
    print(row)

# Idea 3: The 5 stays, but left and right become reflections of EACH OTHER
def make_mirror_image(grid):
    rows, cols = len(grid), len(grid[0])
    center = cols // 2
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if c == center:
                result[r][c] = 5
            elif c < center:
                result[r][c] = grid[r][c]  # Keep left as-is
            else:
                # Mirror from left side
                mirror_c = 2*center - c
                result[r][c] = grid[r][mirror_c]

    return result

